interface Env {
  ASSETS: {
    fetch(request: Request): Promise<Response>;
  };
}

/**
 * Sites/Cloudflare entry point for the Astro-generated static assets.
 * All application HTML remains statically generated by Astro.
 */
export default {
  fetch(request: Request, env: Env): Promise<Response> {
    return env.ASSETS.fetch(request);
  },
};
